  public static Tlscert.TlsCertRenew tlsCertRenewFromBytes(byte[] data) throws ProtoException {
    if (data == null || data.length == 0) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "data is null or empty");
    }
    String dataStr = new String(data).trim();
    if (dataStr.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "empty data after trimming");
    }
    if (dataStr.startsWith("{") || dataStr.startsWith("[")) {
      try {
        return tlsCertRenewFromJson(dataStr);
      } catch (Exception e) {
        // Fall through to try other formats
      }
    }
    if (dataStr.contains(":") && !dataStr.contains("=")) {
      try {
        return tlsCertRenewFromYaml(dataStr);
      } catch (Exception e) {
        // Fall through to try other formats
      }
    }
    if (dataStr.contains("=")) {
      try {
        return tlsCertRenewFromToml(dataStr);
      } catch (Exception e) {
        // Fall through to try binary
      }
    }
    try {
      return tlsCertRenewFromBinary(data);
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL,
          "Failed to parse TlsCertRenew: unsupported format or invalid data: " + e.getMessage(),
          e);
    }
  }

