  public static void validateTlsCertInit(Tlscert.TlsCertInit msg) throws ProtoException {
    if (msg == null) {
      return;
    }
    // Validate serviceName (assert_required)
    if (msg.getServiceName().isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "field serviceName is required");
    }
    // Validate serviceName (assert_min_length: 1)
    if (msg.getServiceName().length() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field serviceName must be at least 1 characters, got: %d",
              msg.getServiceName().length()));
    }
    // Validate instanceId (assert_required)
    if (msg.getInstanceId().isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "field instanceId is required");
    }
    // Validate instanceId (assert_min_length: 1)
    if (msg.getInstanceId().length() < 1) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          String.format(
              "field instanceId must be at least 1 characters, got: %d",
              msg.getInstanceId().length()));
    }
  }

