  // ============ Merge ============
  public static Tlscert.TlsCertClientMsg.Builder mergeTlsCertClientMsg(
      Tlscert.TlsCertClientMsg dst, Tlscert.TlsCertClientMsg src) {
    Tlscert.TlsCertClientMsg.Builder builder = dst.toBuilder();
    if (dst.getMsgCase() == Tlscert.TlsCertClientMsg.MsgCase.MSG_NOT_SET) {
      switch (src.getMsgCase()) {
        case INIT:
          builder.setInit(src.getInit());
          break;
        case CSR:
          builder.setCsr(src.getCsr());
          break;
        default:
          break;
      }
    }
    return builder;
  }

  public static Tlscert.TlsCertInit.Builder mergeTlsCertInit(
      Tlscert.TlsCertInit dst, Tlscert.TlsCertInit src) {
    Tlscert.TlsCertInit.Builder builder = dst.toBuilder();
    if (dst.getServiceName().isEmpty()) {
      builder.setServiceName(src.getServiceName());
    }
    if (dst.getInstanceId().isEmpty()) {
      builder.setInstanceId(src.getInstanceId());
    }
    return builder;
  }

  public static Tlscert.TlsCertCsr.Builder mergeTlsCertCsr(
      Tlscert.TlsCertCsr dst, Tlscert.TlsCertCsr src) {
    Tlscert.TlsCertCsr.Builder builder = dst.toBuilder();
    if (!dst.hasPublicKey() && src.hasPublicKey()) {
      builder.setPublicKey(src.getPublicKey());
    }
    return builder;
  }

  public static Tlscert.TlsCertServerMsg.Builder mergeTlsCertServerMsg(
      Tlscert.TlsCertServerMsg dst, Tlscert.TlsCertServerMsg src) {
    Tlscert.TlsCertServerMsg.Builder builder = dst.toBuilder();
    if (dst.getMsgCase() == Tlscert.TlsCertServerMsg.MsgCase.MSG_NOT_SET) {
      switch (src.getMsgCase()) {
        case CERT:
          builder.setCert(src.getCert());
          break;
        case RENEW:
          builder.setRenew(src.getRenew());
          break;
        case ERROR:
          builder.setError(src.getError());
          break;
        default:
          break;
      }
    }
    return builder;
  }

  public static Tlscert.TlsCertDelivery.Builder mergeTlsCertDelivery(
      Tlscert.TlsCertDelivery dst, Tlscert.TlsCertDelivery src) {
    Tlscert.TlsCertDelivery.Builder builder = dst.toBuilder();
    if (!dst.hasChain() && src.hasChain()) {
      builder.setChain(src.getChain());
    }
    return builder;
  }

  public static Tlscert.TlsCertRenew.Builder mergeTlsCertRenew(
      Tlscert.TlsCertRenew dst, Tlscert.TlsCertRenew src) {
    Tlscert.TlsCertRenew.Builder builder = dst.toBuilder();
    if (dst.getReason().isEmpty()) {
      builder.setReason(src.getReason());
    }
    return builder;
  }

